(function runAction(/*GlideRecord*/ current, /*GlideRecord*/ event, /*EmailWrapper*/ email, /*ScopedEmailLogger*/ logger, /*EmailClassifier*/ classifier) {

	// Implement email action here
	gs.log('InStock Asset - Setting up data source');
var st = "sys_created_onONToday@javascript:gs.beginningOfToday()@javascript:gs.endOfToday()^state=running^sys_transform_map=0a54a8b51300c3c0af7a5d322244b042";
var transHistory = new GlideRecord('sys_import_set_run');
transHistory.addEncodedQuery(st);
transHistory.query();
while (transHistory.next()) {
    gs.sleep(10000);
}

// var sList = new GlideRecord('u_instock_scanned_asset');
// sList.query();
