var nowDate = gs.nowDateTime();
current.name = "Collection Data Source created" + gs.nowDateTime(); //append date time to name of data source for audit
current.import_set_table_name = "collection_import_set";
current.import_set_table_label = "Collections Imports";
current.type = "File";
current.format = "Excel";
current.file_retrieval_method = "Attachment";

var myNewDataSource = current.insert();

gs.log('TD002 - Data source inserted with sys_id - ' + myNewDataSource);

//point the scheduled import record to the new data source



})(current, event, email, logger, classifier);
